/**
 * 按后端过滤出适用的步骤，顺序不变。
 * @param {string|null} backendId 'github' | 'markdown' | 'gitlab'（为空或未知则返回空数组）
 * @returns {ReadonlyArray<Object>}
 */
function guideStepsFor(backendId) {
  try {
    const id = String(backendId || '')
    if (!id) return []
    return GUIDE_STEPS.filter(function (s) {
      return !!(s && Array.isArray(s.backends) && s.backends.indexOf(id) >= 0)
    })
  } catch (e) { return [] }
}

/**
 * 这一步过没过：它的检查项在链快照里全部是 'done' 才算过。
 * 检查项在链快照里根本没有（例如该后端不适用）时一律算没过——宁可再问一次，也不把没有证据当成过了。
 * @param {Object} step GUIDE_STEPS 里的一步
 * @param {Array<{id:string,status:string}>} chainSteps 链快照里的步骤（st.chainSnapshot.steps）
 * @returns {boolean}
 */
function guideStepDone(step, chainSteps) {
  try {
    const ids = step && Array.isArray(step.checks) ? step.checks : []
    if (!ids.length) return false
    const list = Array.isArray(chainSteps) ? chainSteps : []
    const statusOf = {}
    for (let i = 0; i < list.length; i++) {
      const it = list[i]
      if (it && it.id != null) statusOf[String(it.id)] = String((it && it.status) || '')
    }
    return ids.every(function (id) {
      return statusOf[String(id)] === 'done'
    })
  } catch (e) { return false }
}

/**
 * 这一步在链快照里处于哪一种没过：'failed'（至少一项明确失败）还是 'pending'
 * （没有失败、只是还没拿到确定结论，例如网络抖动或超时）。
 * 快照里一项都没有时返回 'absent'（调用处按老口径跳过，不出横幅）。
 * 目前只有登录那一步区分这两种没过，其余步骤照旧走失败那一套。
 * @param {Object} step GUIDE_STEPS 里的一步
 * @param {Array<{id:string,status:string}>} chainSteps 链快照里的步骤
 * @returns {'done'|'failed'|'pending'|'absent'}
 */
function guideStepState(step, chainSteps) {
  try {
    const ids = step && Array.isArray(step.checks) ? step.checks : []
    if (!ids.length) return 'absent'
    const list = Array.isArray(chainSteps) ? chainSteps : []
    const statusOf = {}
    for (let i = 0; i < list.length; i++) {
      const it = list[i]
      if (it && it.id != null) statusOf[String(it.id)] = String((it && it.status) || '')
    }
    const present = ids.filter(function (id) { return statusOf[String(id)] !== undefined && statusOf[String(id)] !== '' })
    if (!present.length) return 'absent'
    if (present.every(function (id) { return statusOf[String(id)] === 'done' })) return 'done'
    if (present.some(function (id) { return statusOf[String(id)] === 'fail' || statusOf[String(id)] === 'current' })) return 'failed'
    return 'pending'
  } catch (e) { return 'pending' }
}

/**
 * 这一步今天该出哪一条横幅：默认就是清单里配的那条；只有登录那一步在查不到
 * （pending）时换成中性那一条（#916）。选哪一步仍由 guideBannerStep 定，这里只定文案。
 */
function guideBannerOf(step, chainSteps) {
  try {
    if (step && String(step.id) === 'gh:authed' && guideStepState(step, chainSteps) === 'pending') return BANNER.ghAuthUnknown
    return (step && step.banner) || null
  } catch (e) { return (step && step.banner) || null }
}

/**
 * 这一步的按钮点下去该干什么：默认就是清单里配的那一种；只有登录那一步在查不到
 * 时改成强制重查（#916，不注入登录指引）。
 */
function guideMissingOf(step, chainSteps) {
  try {
    if (step && String(step.id) === 'gh:authed' && guideStepState(step, chainSteps) === 'pending') return MISSING.ghAuthRecheck
    return (step && step.missing) || null
  } catch (e) { return (step && step.missing) || null }
}

/**
 * 清单里某一步没过时要注入的那句「逐字固定的原话」（这一步不是给固定原话就返回空串）。
 * 用它、而不是各自去 GUIDE_STEPS 里翻一遍：缺 gh 时那句话只有一份 —— 状态栏那条横幅、检查页那一行的
 * 按钮、建仓向导失败时自动注入的那一份，取的都是它（#664 定的口径：一个缺失状态不许有两份说明）。
 * #716：装 CLI 那句话已经挪回后端声明，这一步改成返回「去查哪条提示词」。两种情况都用 guideInjectPromptOf
 * 拿键名更省事，但这条老出口留着 —— 别的后端将来若真给固定原话，仍然走它。
 * @param {string} stepId 步骤 id（例如 'gh:installed'）
 * @returns {string}
 */
function guideInjectTextOf(stepId) {
  try {
    const id = String(stepId == null ? '' : stepId)
    if (!id) return ''
    for (let i = 0; i < GUIDE_STEPS.length; i++) {
      const s = GUIDE_STEPS[i]
      if (s && String(s.id) === id && s.missing && typeof s.missing.text === 'string') return s.missing.text
    }
    return ''
  } catch (e) { return '' }
}

/**
 * 清单里某一步没过时要注入的是**哪一条后端声明提示词**（这一步不是按提示词键注入就返回空串）。
 * 为什么要有它：注入哪段话由清单说了算（清单是顺序与方式的唯一真源），但那段话本身属于具体后端，
 * 住在后端的 prompts 声明里（GitHub 的装 CLI 原话就是 prompts.cliInstall）。调用处拿这个键去问当前
 * 后端要文本，取不到就如实报失败，不静默注入一个键名。
 * @param {string} stepId 步骤 id（例如 'gh:installed'）
 * @returns {string} 提示词键名（例如 'cliInstall'）；这一步不按提示词键注入时是空串
 */
function guideInjectPromptOf(stepId) {
  try {
    const id = String(stepId == null ? '' : stepId)
    if (!id) return ''
    for (let i = 0; i < GUIDE_STEPS.length; i++) {
      const s = GUIDE_STEPS[i]
      if (s && String(s.id) === id && s.missing && typeof s.missing.prompt === 'string') return s.missing.prompt
    }
    return ''
  } catch (e) { return '' }
}

/**
 * 把链快照的步骤按清单排好：清单上的步骤按清单顺序排在前，清单没覆盖的检查项按原有的先后接在后面。
 * 宿主组装 fullSnapshot 时用它（见 src/host/detectChain.js）；界面只照快照渲染，不自己排序。
 * ready 为 'gate' 的步骤不在链快照里（它没有对应检查项），参与排序时自动跳过。
 * @param {ReadonlyArray<Object>} guideSteps 某后端的清单（guideStepsFor 的结果）
 * @param {Array<Object>} chainSteps 链快照里的步骤
 * @returns {Array<Object>} 排好序的新数组（不改动入参）
 */
function orderStepsByGuide(guideSteps, chainSteps) {
  const list = Array.isArray(chainSteps) ? chainSteps : []
  const steps = Array.isArray(guideSteps) ? guideSteps : []
  const byId = {}
  for (let i = 0; i < list.length; i++) {
    const it = list[i]
    if (it && it.id != null && !byId[String(it.id)]) byId[String(it.id)] = it
  }
  const out = []
  const taken = {}
  for (let g = 0; g < steps.length; g++) {
    const step = steps[g]
    if (!step || step.ready === STEP_READY.GATE) continue
    const ids = Array.isArray(step.checks) ? step.checks : []
    for (let c = 0; c < ids.length; c++) {
      const key = String(ids[c])
      if (taken[key] || !byId[key]) continue
      taken[key] = true
      out.push(byId[key])
    }
  }
  for (let i = 0; i < list.length; i++) {
    const it = list[i]
    if (it && it.id != null && taken[String(it.id)]) continue
    out.push(it)
  }
  return out
}
    // src/shared/naming-titles.js —— S2（#452）从 naming-guardian.js 拆出之占位识别、标题清洗截断、草稿档与编号档合成，纯结构、行为零变化。
// 以后谁改它：改占位四式、标题清洗截断规则、草稿档或编号档合成的人。预估约175行，超 350 打回。
// 接线：纯函数，无输入输出、无内核依赖（promptLang 为可选闭包自由变量，typeof 守卫）；不引用跟踪与归属文件（墙要求）；
//   宿主半运行时引用本文件（与另两文件合并），界面半由 scripts/build.mjs 以 SHARED_SPLICE 拼回闭包。

/**
 * src/shared/naming-titles.js — 命名守护标题合成半（#265/#205 · 从 naming-guardian.js 拆出，S2 #452）。
 *
 * 契约（#264 规约 · 单缝原则）：本文件是标题合成的真源 —— 占位识别、标题合成（草稿档 + 编号档，
 * 清洗截断沿用 #205 既有规则与 UTF-8 120 字节预算）。分档状态机、跟踪态、计划单见 naming-tracking.js，
 * 编号归属见 naming-attribution.js；三文件之间不互相引用（墙要求）。
 * 宿主半运行时引用本文件（与另两文件合并）；界面半由 scripts/build.mjs 以 SHARED_SPLICE 方式将
 * 三文件声明体拼回 src/client/index.js 闭包（一源两物，与 kernel/leaf 拼接同模式），
 * 两半均不另写第二处命名实现。
 *
 * 生效日期：2026-08-28
 * 效力规则：本文件以 #264 规约 + #260 五决议 + ADR 20260827 为基线；与更早方案冲突以
 *           本规约为准；未来任何定版方案若改动本规约，以未来版本为准（见 CONTEXT.md「版本与效力」）。
 *
 * 本模块为纯函数：无输入输出、无内核依赖（promptLang 为可选闭包自由变量，typeof 守卫），
 * 可被 Node 校验测试直接引用复跑。
 */

const NAMING_CORE_VERSION = 1

// ============ 占位（P0）============
// 占位（#211 定版 · 跟随 harness 语言 + 动作分形）：
//   原四式：[New] 新建需求 / [New] 新建 Bug / New Requirement / New Bug（历史兼容保留）；
//   八个动作：诊断/修复/讨论/研究/原型/接手/补充/体检 —— 界面上每个建会话的入口各占一个（见 ACTION_WORDS）；
//   交接历史词（交接 / Handoff）仍视为占位，草稿时原样保留该词，不强制改成接手。
const SESSION_TITLE_PREFIX = '[New]'

const PLACEHOLDER_TITLES = {
  zh: { requirement: '新建需求', bug: '新建 Bug' },
  en: { requirement: 'New Requirement', bug: 'New Bug' },
}

// 动作中英文（用户定稿：占位加动作字，草稿落为对应动作档，不碰编号档）。八条各对应界面一个真实入口：
// 诊断/修复/讨论/研究/原型（行级动作与详情页顶栏）、接手（交接第二击）、补充（沉淀）、体检（体检按钮）。
const ACTION_WORDS = {
  diagnose: { zh: '诊断', en: 'Diagnose' },
  fix: { zh: '修复', en: 'Fix' },
  discuss: { zh: '讨论', en: 'Discuss' },
  research: { zh: '研究', en: 'Research' },
  prototype: { zh: '原型', en: 'Prototype' },
  handoff: { zh: '接手', en: 'Handoff' },
  supplement: { zh: '补充', en: 'Supplement' },
  health: { zh: '体检', en: 'Health check' },
}

// 历史兼容：交接旧词仍算占位（新起统一用接手，旧会话的交接不判死）
const LEGACY_PLACEHOLDER_WORDS = ['交接', 'Handoff']

function allPlaceholderWords() {
  const out = []
  out.push(PLACEHOLDER_TITLES.zh.requirement, PLACEHOLDER_TITLES.zh.bug)
  out.push(PLACEHOLDER_TITLES.en.requirement, PLACEHOLDER_TITLES.en.bug)
  for (const k in ACTION_WORDS) {
    const w = ACTION_WORDS[k]
    if (w) { out.push(w.zh, w.en) }
  }
  for (let i = 0; i < LEGACY_PLACEHOLDER_WORDS.length; i++) out.push(LEGACY_PLACEHOLDER_WORDS[i])
  return out
}

function isPlaceholderTitle(s) {
  const raw = String(s == null ? '' : s).trim()
  const words = allPlaceholderWords()
  for (let i = 0; i < words.length; i++) {
    if (raw === SESSION_TITLE_PREFIX + ' ' + words[i]) return true
  }
  return false
}

/** 生成占位标题（纯语言参数；lang 缺省 zh，'en' 开头即英文）。type 支持：bug/requirement + 动作键。 */
function placeholderTitleFor({ type, lang }) {
  const t = String(type || '').toLowerCase()
  const en = typeof lang === 'string' && lang.indexOf('en') === 0
  // 七动作优先（diagnose/fix/discuss/research/prototype/handoff/supplement，前缀匹配即可）
  for (const k in ACTION_WORDS) {
    if (t.indexOf(k) === 0 || t === ACTION_WORDS[k].zh || t.toLowerCase() === ACTION_WORDS[k].en.toLowerCase()) {
      return SESSION_TITLE_PREFIX + ' ' + (en ? ACTION_WORDS[k].en : ACTION_WORDS[k].zh)
    }
  }
  const bug = t.indexOf('bug') >= 0
  const w = (en ? PLACEHOLDER_TITLES.en : PLACEHOLDER_TITLES.zh)[bug ? 'bug' : 'requirement']
  return SESSION_TITLE_PREFIX + ' ' + w
}

/**
 * 兼容签名 (type, lang?)：Tabs/StatusBar 沿用旧调用形态；lang 缺省按 harness 语言
 * （promptLang 为闭包自由变量，在宿主/Node 独立加载时 typeof 守卫安全降级 zh）。
 */
function newSessionTitleNew(type, lang) {
  let en = false
  if (lang) {
    try { en = String(lang).toLowerCase().indexOf('en') === 0 } catch (e) {}
  } else {
    try { en = (typeof promptLang === 'function' ? promptLang() === 'en' : false) } catch (e) {}
  }
  return placeholderTitleFor({ type: type, lang: en ? 'en' : 'zh' })
}

// ============ 标题清洗/截断/编号档合成（#205 契约 · 迁移自 router.js）============
const SESSION_TITLE_MAX_BYTES = 120

// 契约 #205：会话标题 = [#n] + 单空格 + 清洗后标题（120 bytes 预算，前缀永不截断）
const SESSION_TITLE_RE = /^\[#\d+\] .+/

const SESSION_TITLE_RE_ALLOW_BARE = /^\[#\d+\](?: .+)?$/

/** 编号档识别：`[#n]` 或 `[#n] 标题` → { number, title }；不是编号档回 null。
 *  注册通道用它把「在新会话打开」这类会话按编号档收编，好让宿主首句名盖不掉它。 */
function parseNumberedTitle(s) {
  const m = /^\s*\[#(\d+)\](?:\s+([\s\S]*))?$/.exec(String(s == null ? '' : s))
  if (!m) return null
  // numberText 保留原样（本地 Markdown 后端的地图编号是 '00'，只留数值会被改写成 [0]，名字就变形了）
  return { number: Number(m[1]), numberText: m[1], title: cleanTitleText(m[2] || '') }
}

/** 清洗：剥控制/方向/隐形字符，空白归一为单空格并 trim，emoji 保留（沿用 #205 既有规则）。 */
function cleanTitleText(s) {
  let t = String(s || '')
  t = t.replace(/\x1B\][^\x07]*\x07/g, '').replace(/\x1B\[[0-9;]*[A-Za-z]/g, '').replace(/\x1B[^\x5B\x5D\x07]/g, '')
  t = t.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, ' ')
  t = t.replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g, ' ')
  t = t.replace(/\s+/g, ' ').trim()
  return t
}

function utf8Bytes(str) {
  if (typeof Buffer !== 'undefined' && Buffer.byteLength) return Buffer.byteLength(str, 'utf8')
  try { return new TextEncoder().encode(str).length } catch (e) { return str.length }
}

/** UTF-8 字节预算截断：prefix + 单空格 + title（超长尾部截 + …），prefix 永不截断。 */
function truncateTitleUtf8(prefix, title, maxBytes) {
  const sep = ' '
  const base = prefix + sep
  const baseBytes = utf8Bytes(base)
  if (utf8Bytes(title) + baseBytes <= maxBytes) return title
  const ellipsis = '…'
  const ellipsisBytes = utf8Bytes(ellipsis)
  let acc = 0; let out = ''
  for (const ch of title) {
    const b = utf8Bytes(ch)
    if (baseBytes + acc + b + ellipsisBytes > maxBytes) break
    acc += b; out += ch
  }
  return out.trimEnd() + ellipsis
}

/** 编号档（P2）标题合成：[#n] + 清洗/截断后标题（#205 契约）。 */
function newSessionTitle(t) {
  const raw = (t && t.numberText != null && String(t.numberText).trim()) ? String(t.numberText).trim() : (t && t.number != null ? t.number : '')
  const n = String(raw).trim()
  if (!/^\d+$/.test(n)) throw new Error('newSessionTitle: invalid number ' + n)
  const prefix = '[' + '#' + n + ']'
  let title = cleanTitleText(t && t.title != null ? t.title : '')
  if (!title) return prefix
  title = truncateTitleUtf8(prefix, title, SESSION_TITLE_MAX_BYTES)
  return prefix + ' ' + title
}

// ============ 草稿档（P1）============
// 档位词按本机语言落地（界面半按语言取词，计划单本身不含语言字面量 —— #264 D2）
const DRAFT_WORDS = { zh: '草稿', en: 'Draft' }

const DRAFT_TITLE_RE = /^\[(草稿|Draft)\](?: .+)?$/

function draftWordFor(lang) {
  return typeof lang === 'string' && lang.indexOf('en') === 0 ? DRAFT_WORDS.en : DRAFT_WORDS.zh
}

/**
 * 草稿标题合成：面包屑语义线索优先（[草稿][新增需求/BUG] <线索>），无线索则仅类型标签；
 * 清洗截断沿用 #205 规则与 UTF-8 120 字节总预算（含前缀，前缀永不截断）。
 * baselineTitle 用于区分“新增需求”与“新增BUG”（取自注册占位），为用户要求“[草稿][新增需求]xxx”而加。
 */
function composeDraftTitle({ hint, lang, baselineTitle }) {
  const prefix = '[' + draftWordFor(lang) + ']'
  const isEn = String(lang).toLowerCase().indexOf('en') === 0
  let typeTag = ''
  if (baselineTitle) {
    const bt = String(baselineTitle)
    // 七动作优先：基线含哪个动作词就落哪个动作档（如 [New] 诊断 → [草稿][诊断]）
    let hit = null
    for (const k in ACTION_WORDS) {
      const w = ACTION_WORDS[k]
      if (!w) continue
      if (bt.indexOf(w.zh) >= 0 || bt.toLowerCase().indexOf(w.en.toLowerCase()) >= 0) { hit = w; break }
    }
    // 历史兼容：旧交接词仍保留原词
    if (!hit) {
      if (bt.indexOf('交接') >= 0) hit = { zh: '交接', en: 'Handoff' }
    }
    if (hit) typeTag = '[' + (isEn ? hit.en : hit.zh) + ']'
    else {
      const isBug = /Bug/i.test(bt)
      if (isBug) typeTag = (isEn ? '[New Bug]' : '[新增BUG]')
      else typeTag = (isEn ? '[New Requirement]' : '[新增需求]')
    }
  }
  const fullPrefix = typeTag ? prefix + typeTag : prefix
  const rawHint = cleanTitleText(hint || '')
  if (!rawHint) return fullPrefix
  // 线索本身只是类型词（占位派生的“新建需求”“诊断”等）时不再叠字，直接裸档；
  // 无基线（无标签）时不去重，避免把有效线索吞掉。
  if (typeTag) {
    const condensed = String(rawHint).toLowerCase().replace(/\s+/g, '')
    const bareWords = ['新建需求', '新增需求', '新建bug', '新增bug', 'newrequirement', 'newbug',
      '诊断', '修复', '讨论', '研究', '原型', '接手', '补充', '交接', '体检',
      'diagnose', 'fix', 'discuss', 'research', 'prototype', 'handoff', 'supplement', 'health', 'healthcheck']
    if (bareWords.indexOf(condensed) >= 0) return fullPrefix
  }
  return fullPrefix + ' ' + truncateTitleUtf8(fullPrefix, rawHint, SESSION_TITLE_MAX_BYTES)
} // src/shared/naming-tracking.js —— S2（#452）从 naming-guardian.js 拆出之值比对锁、跟踪态与状态机、失败重试、计划单。
// 接线：不引用标题与归属文件（墙要求）；编号分支要用的标题合成小函数在文件内放一份（tracking 前缀），与 naming-titles.js 同源，改动两处同改。

/**
 * src/shared/naming-tracking.js — 命名守护跟踪推进半（#264/#267 · 从 naming-guardian.js 拆出，S2 #452）。
 * 契约（#264 · 单缝原则）：本文件是跟踪推进的真源 —— 值比对锁、分歧归因、跟踪态与分档状态机、计划单、失败重试。
 * 标题合成见 naming-titles.js，编号归属见 naming-attribution.js；三文件互不引用，宿主半运行时引用本文件，界面半由
 * scripts/build.mjs 拼回 src/client/index.js 闭包（一源两物）。纯函数，Node 可直跑。
 * 生效 2026-08-28，以 #264 规约 + #260 五决议 + ADR 20260827 为基线，未来定版以未来为准。
 */

/** 值比对真检测（#264 D3/F5）：@returns 'unlocked' | 'locked' | 'unknown' —— 机器写过就与 lastMachineTitle 比，
 * 没写过就与注册基准比，两条都不等即判手改；当前标题不可读（null/空串）→ unknown（调用方跳过本轮，不盲写）。 */
function evaluateRenameLock({ currentTitle, lastMachineTitle, baselineTitle }) {
  const cur = currentTitle == null ? null : String(currentTitle)
  if (cur === null || cur === '') return 'unknown'
  const last = lastMachineTitle == null ? null : String(lastMachineTitle)
  const base = baselineTitle == null ? null : String(baselineTitle)
  if (last !== null) return cur === last ? 'unlocked' : 'locked'
  if (base !== null) return cur === base ? 'unlocked' : 'locked'
  // 无基准（防御异常态）：无信息可判，放行由调用方决定
  return 'unlocked'
}

// ============ 原生首句标题免锁（#746 · 0.1.7 底座行为）============
// 底座在首条用户消息发出后会把首句裁剪成会话标题（与机器、用户都无关）；旧判据把它当手改永久
// 锁定。免锁只认派生关系：现名等于首句，或以首句开头且不短于下限（归一空白后比）。真手改仍锁定。
function normTitleLine(s) { return String(s == null ? '' : s).replace(/\s+/g, ' ').trim() }
// 首句截断那条路的最小长度（见 isNativeAutoTitle 里的理由）。
const NATIVE_TITLE_MIN_CHARS = 20
function isNativeAutoTitle({ currentTitle, firstUserText }) {
  const cur = normTitleLine(currentTitle), first = normTitleLine(firstUserText)
  if (!cur || !first) return false
  if (cur === first) return true
  // 截断那一路要有下限：底座写的是首句的截断，长度跟首句同量级；不加下限的话「1」这种短串
  // 也算首句派生，用户手改成一个短名就会被我们盖掉（对抗审查 B）。20 只是下限，可随真机观察再调。
  if (cur.length < NATIVE_TITLE_MIN_CHARS) return false
  return first.indexOf(cur) === 0
}

// ============ 分歧归因（唯一判据 · #746 与后续对抗审查、2026-10-03 标题来源事实的合并）============
// 执行点只问这一个函数「现在这个名字为什么不是我们要的」，六种答案各带去处：in-place 已在位不动；
// never-wrote 我们那次改名没落地（直接写）；auto-title 底座自动取的（可盖回）；first-sentence 底座首句名
// （无事实时的旧判据，可盖回）；hand-edit 别人写的（永久让位，理由进日志）；unknown-title 读不到（不动）。
const DIVERGENCE = {
  IN_PLACE: 'in-place',
  NEVER_WROTE: 'never-wrote',
  AUTO_TITLE: 'auto-title',
  FIRST_SENTENCE: 'first-sentence',
  HAND_EDIT: 'hand-edit',
  UNKNOWN_TITLE: 'unknown-title',
}

function classifyDivergence({ currentTitle, lastMachineTitle, baselineTitle, baselineIsOurs, firstUserText, targetTitle, titleSource }) {
  try {
    const cur = normTitleLine(currentTitle)
    if (!cur) return DIVERGENCE.UNKNOWN_TITLE
    // 第一问必须是「这条名是不是我们自己写的」：我们写过的（目标名 / 机器最后写入值 / 基准名）就没有分歧。
    // 少了这一问，宿主刚改完、客户端拿同一张单再跑一遍时会把正确的名字判成手改 —— 每成功一次就锁死一次。
    const ours = (lastMachineTitle != null && cur === normTitleLine(lastMachineTitle)) ||
      (baselineIsOurs !== false && baselineTitle != null && cur === normTitleLine(baselineTitle)) ||
      (targetTitle != null && cur === normTitleLine(targetTitle))
    if (ours) return DIVERGENCE.IN_PLACE
    if (baselineIsOurs === false && lastMachineTitle == null) return DIVERGENCE.NEVER_WROTE
    // 事实优先：宿主随单下发的「这条名是谁写的」；与现名逐字对上才采信，对不上（标题已变）当没有。
    const ts = titleSource
    if (ts && typeof ts === 'object' && normTitleLine(ts.title) === cur) {
      const k = String(ts.kind || '')
      return (k === 'fallback' || k === 'provider') ? DIVERGENCE.AUTO_TITLE : DIVERGENCE.HAND_EDIT
    }
    if (isNativeAutoTitle({ currentTitle: currentTitle, firstUserText: firstUserText })) return DIVERGENCE.FIRST_SENTENCE
    return DIVERGENCE.HAND_EDIT
  } catch (e) { return DIVERGENCE.UNKNOWN_TITLE }
}

// ============ 跟踪态结构 + 分档状态机 ============
// #264：结构 { sessionId, stage, lastMachineTitle, locked, repoKey, createdAt, updatedAt }；本实现追加
// baselineTitle/baselineIsOurs（注册那一次写下的名、以及它是不是我们写的）、hint（语义线索）。
const NAMING_STAGES = {
  PLACEHOLDER: 'placeholder',
  DRAFT: 'draft',
  NUMBERED: 'numbered',
  REFINED: 'refined',   // P3 精修档：一期仅占位（#264 Out of Scope · #260 决议「实现分期」）
}

// ---- P3 精修二期预留（#267）----
// 本期不含存量回填（#261 否决）也不含 LLM 精修；REFINED 零消费，planOrderFor 对它恒不出单。二期接缝：① reducer 增 'refined' 入账；② planOrderFor 出 kind:'refined' 单；③ 界面半按 kind 分派。

// 线索宽限：先裸档后升级语义，注册后即出裸档单；后到线索可再升级一次（用完即记 lastDraftHint）。
const NAMING_HINT_GRACE_MS = 0

function createTrackingState({ sessionId, baselineTitle, repoKey, cwd, baselineIsOurs }) {
  const now = Date.now()
  return {
    sessionId: String(sessionId || ''),
    stage: NAMING_STAGES.PLACEHOLDER,
    lastMachineTitle: null,
    baselineTitle: String(baselineTitle || ''),
    // 基线这条名是不是我们自己写的（注册那次改名成功即 true）。旧账没这个字段按 true 容错，行为与加它之前一致。
    baselineIsOurs: baselineIsOurs === false ? false : true,
    locked: false,
    hint: null,
    repoKey: repoKey || null,
    // #266 追加：cwd（索引快照执行上下文）、number/numberTitle（获号信息）、numberedDone（编号档 rename 已落定，防重复出单/循环）——盘上旧账兼容。
    cwd: cwd || null,
    number: null,
    numberTitle: null,
    numberedDone: false,
    // #746：上次草稿升级用掉的线索（后到不同线索可再升级一次；无/相同则不出单）
    lastDraftHint: null,
    // #267 追加：界面执行失败的有限重试入账（failCount=连败次数 / lastFailAt=末次失败时刻 / lastError=末次错误摘要；成功改名与全新编号跃迁清零重来）。
    failCount: 0,
    lastFailAt: null,
    lastError: null,
    // #746 追加：首轮摘要只调一次（summaryOnce=好线索已入账 / summaryFailed=调模型失败永不补调；读不到两段、没路由等未遂不记旗，可再试）。
    summaryOnce: false,
    summaryFailed: false,
    createdAt: now,
    updatedAt: now,
  }
}

/**
 * 分档状态机（纯 reducer）：所有信号（注册/认领推送线索/机器改名单回报/手改锁定/编号预留）
 * 都汇入同一入口 —— #264 US14「所有信号汇入同一个分档状态机」。
 */
function reduceTrackingState(state, event) {
  if (!state) return state
  const ev = event || {}
  const next = Object.assign({}, state)
  if (ev.type === 'signal') {
    if (ev.hint && !next.locked) {
      next.hint = String(ev.hint).slice(0, 80)
      next.updatedAt = Date.now()
    }
  } else if (ev.type === 'renamed') {
    // 界面半回报：机器成功改名（title = DSH 归一化后实际接受的标题）
    if (!next.locked && ev.title) {
      if (next.stage === NAMING_STAGES.PLACEHOLDER) next.stage = NAMING_STAGES.DRAFT
      // #746：草稿档落定时记下用掉的线索，后到不同线索才能再升级（防重复/循环）
      if (next.stage === NAMING_STAGES.DRAFT) next.lastDraftHint = next.hint || null
      next.lastMachineTitle = String(ev.title)
      // #267：任何成功改名即清账重来（有限重试预算只针对连续失败的同一目标）
      next.failCount = 0; next.lastFailAt = null; next.lastError = null
      // #266：编号档 rename 落定判定 —— 接受标题携带同一 [#n] 前缀即视为编号档完成
      // （防止非编号名（如草稿档）的 renamed 抢占 numberedDone，杜绝重复出单/循环）
      // 对抗 K2：前缀按编号原文算（00 号是 [#00] 不是 [#0]），否则原文号永不落定。
      if (next.stage === NAMING_STAGES.NUMBERED && next.number != null) {
        const pfxNum = (next.numberText != null && String(next.numberText).trim() !== '') ? String(next.numberText).trim() : String(next.number)
        const pfx = '[' + '#' + pfxNum + ']'
        if (String(ev.title).indexOf(pfx) === 0) next.numberedDone = true
      }
      next.updatedAt = Date.now()
    }
  } else if (ev.type === 'locked') {
    next.locked = true
    next.updatedAt = Date.now()
  } else if (ev.type === 'numbered') {
    // #266 编号信号（host 索引差值/即时信号消费）。守卫：#264 手改锁定永不触碰；
    // 已有编号且不同 → 防串名（AC5）；相同编号 → 允许幂等重放携带标题。
    if (next.locked || ev.number == null) return state
    const evNum = Number(ev.number)
    if (!isFinite(evNum) || evNum < 0) return state   // 0 是合法编号（本地 Markdown 后端的地图就是 00）；编号原文随事件带走
    next.numberText = (ev.numberText != null ? String(ev.numberText) : String(next.number == null ? evNum : next.number)).slice(0, 20)
    if (next.number != null && Number(next.number) !== evNum) return state
    const freshNumbered = next.number == null   // 全新获号（非幂等重放）：换目标即重新开预算（#267）
    next.stage = NAMING_STAGES.NUMBERED
    next.number = evNum
    if (ev.title != null) next.numberTitle = String(ev.title).slice(0, 500)
    if (freshNumbered) { next.failCount = 0; next.lastFailAt = null; next.lastError = null }
    next.updatedAt = Date.now()
  } else if (ev.type === 'renameFailed') {
    // #267：界面半执行改名的失败回报入账（host wf.namingResult 消费；错误摘要限长防膨胀）。
    // 锁定会话不再出单，理论收不到本事件 —— 防御性忽略。
    if (!next.locked) {
      next.failCount = ((next.failCount || 0) + 1)
      next.lastFailAt = Date.now()
      next.lastError = String(ev.error || 'rename failed').slice(0, 200)
      next.updatedAt = Date.now()
    }
  } else if (ev.type === 'summaryDone') {
    // #746：首轮摘要好线索入账（hint 由摘要任务随事件带来，一并记 summaryOnce；只调一次）。
    if (!next.locked) {
      if (ev.hint) next.hint = String(ev.hint).slice(0, 80)
      next.summaryOnce = true
      next.updatedAt = Date.now()
    }
  } else if (ev.type === 'summaryFailed') {
    // #746：调模型失败永不补调（与改名重试预算无关，互不拖累）。
    if (!next.locked) { next.summaryFailed = true; next.updatedAt = Date.now() }
  }
  return next
}

// ============ 失败可见性与有限重试（#267 · F4）============
/**
 * 执行失败由本模块统一裁定（#264 F4：失败进入有限重试，放弃则升级为面板级可见提醒）。
 * reducer 入账 'renameFailed' + 下列纯函数：连败计数与末次失败时刻入态；冷却窗内不重复出单
 * （给瞬时故障自愈窗口）；同一目标连败达 NAMING_RETRY_MAX → 定败，planOrderFor 不再出单，
 * namingFailureInfo 出画像供宿主塞进 wf.namingPlan 的 failures，界面落 store 画常驻横幅；
 * 化解两条（手改 → locked；值一致收敛 → renamed）都会自动撤下横幅。
 */
const NAMING_RETRY_MAX = 3

const NAMING_RETRY_COOLDOWN_MS = 45000

/** 定败画像（供面板呈现 + 协商化解判定）；未达预算上限 / 已锁 → null。 */
function namingFailureInfo(state) {
  if (!state || state.locked) return null
  if ((state.failCount || 0) < NAMING_RETRY_MAX) return null
  return {
    sessionId: state.sessionId,
    stage: state.stage,
    kind: state.stage === NAMING_STAGES.NUMBERED ? 'numbered' : 'draft',
    hint: state.hint || null,
    number: state.number == null ? null : Number(state.number),
    numberTitle: state.numberTitle || '',
    error: state.lastError || 'rename failed',
    count: state.failCount || 0,
    lastFailAt: state.lastFailAt == null ? null : state.lastFailAt,
    lock: {
      lastMachineTitle: state.lastMachineTitle,
      baselineTitle: state.baselineTitle,
      locked: state.locked,
    },
  }
}

// 订单里那份锁信息（值比对锁 + 归因要用的基准事实）。三处出单共用一份，免得各写各的漏字段。
function orderLockOf(state) {
  return {
    lastMachineTitle: state.lastMachineTitle,
    baselineTitle: state.baselineTitle,
    baselineIsOurs: state.baselineIsOurs !== false,
    locked: state.locked,
  }
}

/**
 * 待办改名计划单（纯函数产出）：locked / 非占位档 → 无单（草稿档后到不同线索除外）；
 * 有线索 → 携线索；无线索但过线索宽限 → 裸档；未过宽限 → 等待；
 * 草稿档落定后后到不同线索 → 再升级一次（#746）。
 * 订单只携带会话标识与目标语义段信息，不含语言相关字面量（#264 D2）。
 */
function planOrderFor(state, now, hintGraceMs, currentTitle) {
  if (!state) return null
  if (state.locked) return null
  // #267：有限重试门控 —— 连败达预算上限 → 定败不再出单（面板呈现接管）；
  // 冷却窗内不重复出单，瞬时故障等下一窗口自愈。
  if ((state.failCount || 0) >= NAMING_RETRY_MAX) return null
  {
    const tsGate = typeof now === 'number' ? now : Date.now()
    if (state.lastFailAt != null && (tsGate - state.lastFailAt) < NAMING_RETRY_COOLDOWN_MS) return null
  }
  // #266：编号档订单（编号 + issue 标题，语言无关，[#n] 前缀由合成函数保证）；给了 currentTitle 就按实际标题判
  // ——实际标题与目标不符即出单（宿主首句名盖掉 [#n] 名的那种靠它盖回）；没给则沿落定标记与机器最后写入值收敛。
  if (state.stage === NAMING_STAGES.NUMBERED) {
    if (state.number == null) return null
    const title = state.numberTitle || ''
    let target = null
    try { target = trackingNewSessionTitle({ number: state.number, numberText: state.numberText, title: title }) } catch (e) { return null }
    const cur = (typeof currentTitle === 'string' && currentTitle) ? currentTitle : null
    if (cur === target) return null
    if (!cur && (state.numberedDone || (state.lastMachineTitle != null && state.lastMachineTitle === target))) return null
    return {
      sessionId: state.sessionId,
      kind: 'numbered',
      number: state.number,
      numberText: state.numberText || String(state.number),
      title: title,
      lock: orderLockOf(state),
    }
  }
  if (state.stage !== NAMING_STAGES.PLACEHOLDER) {
    // #746：草稿档落定后，后到不同线索可再升级一次（无线索或与上次已用一致 → 不出单，防循环）；被盖回那种也走这里
    if (state.stage !== NAMING_STAGES.DRAFT) return null
    // 实际标题已不是机器最后写下的那个（多半是底座首句名又盖了一次）→ 补一单盖回去；
    // 真手改由执行点的归因函数拦下并记账锁定，不会反复改名。
    const curDraft = (typeof currentTitle === 'string') ? currentTitle : null
    const clobbered = !!(curDraft && state.lastMachineTitle != null && curDraft !== state.lastMachineTitle)
    if (!clobbered && (!state.hint || state.hint === (state.lastDraftHint || null))) return null
    return {
      sessionId: state.sessionId,
      kind: 'draft',
      hint: state.hint,
      lock: orderLockOf(state),
    }
  }
  const ts = typeof now === 'number' ? now : Date.now()
  const grace = typeof hintGraceMs === 'number' ? hintGraceMs : NAMING_HINT_GRACE_MS
  if (!state.hint && (ts - (state.createdAt || ts)) < grace) return null
  return {
    sessionId: state.sessionId,
    kind: 'draft',
    hint: state.hint || null,
    lock: {
      lastMachineTitle: state.lastMachineTitle,
      baselineTitle: state.baselineTitle,
      locked: state.locked,
    },
  }
}

// ---- 与 naming-titles.js 同源（墙要求不互相引用；改动时两处同改）----
// 计划单编号分支要用的标题合成小函数（清洗、字节预算、截断、合成），改名前缀 tracking，避免三文件拼回
// 同一个界面闭包时与标题文件重名。逻辑与 naming-titles.js 内同名函数逐行一致。
const TRACKING_SESSION_TITLE_MAX_BYTES = 120

function trackingCleanTitleText(s) {
  let t = String(s || '')
  t = t.replace(/\x1B\][^\x07]*\x07/g, '').replace(/\x1B\[[0-9;]*[A-Za-z]/g, '').replace(/\x1B[^\x5B\x5D\x07]/g, '')
  t = t.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, ' ')
  t = t.replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g, ' ')
  t = t.replace(/\s+/g, ' ').trim()
  return t
}

function trackingUtf8Bytes(str) {
  if (typeof Buffer !== 'undefined' && Buffer.byteLength) return Buffer.byteLength(str, 'utf8')
  try { return new TextEncoder().encode(str).length } catch (e) { return str.length }
}

function trackingTruncateTitleUtf8(prefix, title, maxBytes) {
  const sep = ' '
  const base = prefix + sep
  const baseBytes = trackingUtf8Bytes(base)
  if (trackingUtf8Bytes(title) + baseBytes <= maxBytes) return title
  const ellipsis = '…'
  const ellipsisBytes = trackingUtf8Bytes(ellipsis)
  let acc = 0; let out = ''
  for (const ch of title) {
    const b = trackingUtf8Bytes(ch)
    if (baseBytes + acc + b + ellipsisBytes > maxBytes) break
    acc += b; out += ch
  }
  return out.trimEnd() + ellipsis
}

function trackingNewSessionTitle(t) {
  const n = ((t && t.numberText != null && String(t.numberText).trim()) ? String(t.numberText).trim() : String(t && t.number != null ? t.number : '')).trim()
  if (!/^\d+$/.test(n)) throw new Error('newSessionTitle: invalid number ' + n)
  const prefix = '[' + '#' + n + ']'
  let title = trackingCleanTitleText(t && t.title != null ? t.title : '')
  if (!title) return prefix
  title = trackingTruncateTitleUtf8(prefix, title, TRACKING_SESSION_TITLE_MAX_BYTES)
  return prefix + ' ' + title
} // src/shared/naming-attribution.js —— S2（#452）从 naming-guardian.js 拆出之编号归属四个函数，纯结构、行为零变化。
// 以后谁改它：改建号感知、编号归属、语义相关性判定的人。预估约150行，超 350 打回。
// 接线：不引用标题与跟踪文件（墙要求）；语义相关性判定要用的清洗小函数与等待状态判定要用的档位常量在文件内各放一份
//   （attribution 前缀），分别与 naming-titles.js、naming-tracking.js 同源，改动时一起改；拼接标记见 scripts/build.mjs 与 src/client/index.js。

/**
 * src/shared/naming-attribution.js — 命名守护编号归属半（#266 建号感知 · 从 naming-guardian.js 拆出，S2 #452）。
 *
 * 契约：本文件是编号归属的真源 —— 当前索引相对上一快照的新增编号、等待编号状态判定、语义相关性判定、
 * 编号归属（纯函数，每仓库一次调用）。宿主半调用；界面半无编号来源，仅消费编号订单。标题合成见 naming-titles.js，
 * 跟踪推进见 naming-tracking.js；三文件之间不互相引用（墙要求）。
 *
 * 生效日期：2026-08-28
 * 效力规则：本文件以 #264 规约 + #260 五决议 + ADR 20260827 为基线；与更早方案冲突以
 *           本规约为准；未来任何定版方案若改动本规约，以未来版本为准（见 CONTEXT.md「版本与效力」）。
 *
 * 本模块为纯函数：无输入输出，可被 Node 校验测试直接引用复跑（与另两文件合并）。
 */

// ---- 与 naming-titles.js 同源（墙要求不互相引用；改动时两处同改）----
// 语义相关性判定要用的标题清洗小函数，改名前缀 attribution，避免三文件拼回同一个界面闭包时与标题文件重名。
// 逻辑与 naming-titles.js 内 cleanTitleText 逐行一致。
function attributionCleanTitleText(s) {
  let t = String(s || '')
  t = t.replace(/\x1B\][^\x07]*\x07/g, '').replace(/\x1B\[[0-9;]*[A-Za-z]/g, '').replace(/\x1B[^\x5B\x5D\x07]/g, '')
  t = t.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, ' ')
  t = t.replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g, ' ')
  t = t.replace(/\s+/g, ' ').trim()
  return t
}

// ---- 与 naming-tracking.js 同源（墙要求不互相引用；改动时两处同改）----
// 等待编号状态判定要用的档位常量。值与 naming-tracking.js 内 NAMING_STAGES 逐项一致。
const ATTRIBUTION_NAMING_STAGES = { PLACEHOLDER: 'placeholder', DRAFT: 'draft', NUMBERED: 'numbered', REFINED: 'refined' }

// ============ 编号归属（#266 · 建号感知 · issue 索引差值纯函数）============
// 底座（#264 F1/F2 修复义务）：宿主周期性快照仓库 issue 列表，新出现的编号归属给同仓库
// 最早仍处占位/草稿档的受踪会话（多候选歧义取最早；无可归者不入计划单）。判定的唯一
// 真源 = 本模块（host 半调用；client 半无编号来源，仅消费 numbered 订单）。

/** 当前索引相对上一快照新增的编号（升序；prev 为空视为基线，无新增）。 */
function newNumbersSince(prevIndex, currIndex) {
  const out = []
  if (!currIndex || typeof currIndex !== 'object') return out
  for (const k of Object.keys(currIndex)) {
    const n = Number(k)
    if (!isFinite(n) || n <= 0) continue
    if (!prevIndex || !Object.prototype.hasOwnProperty.call(prevIndex, k)) out.push(n)
  }
  out.sort(function (a, b) { return a - b })
  return out
}

/** 是否仍处于「等待编号」状态：未锁、尚未获号、仍处占位/草稿档。 */
function isNumberAwaitStage(state) {
  return !!(state && !state.locked && state.number == null &&
    (state.stage === ATTRIBUTION_NAMING_STAGES.PLACEHOLDER || state.stage === ATTRIBUTION_NAMING_STAGES.DRAFT))
}

/**
 * 编号归属（纯函数 · 每仓库一次调用）：对新增编号（升序）逐一分配给候选受踪会话
 * （同仓库、最早者优先：createdAt → updatedAt → sessionId 三级排序保证确定性）；
 * 候选耗尽即止——剩余编号不入计划单，留待后续快照（无可归者不入计划单）。
 * @returns [{ sessionId, number, title }]
 */
/**
 * 语义相关性判定（#315 加固 · 高精度优先）
 * 目标：会话重命名必须贴合其真实任务，宁可不改名也不错配。
 * 当 hint 与新 issue 标题完全无关时，不应配号。
 * 规则（宁严勿宽）：
 * - 先经 cleanTitleText 与去前缀（“任务: ”等）清洗，排除通用前缀误判；
 * - 精确相等即相关；
 * - 长度≥4 的包含即相关（避免短词如“修复”2字误判）；
 * - 否则要求共享长度≥4 的连续子串（对中文/英文均有效）；
 * - 短串（<4）仅精确相等才算相关，避免 “111” 误配。
 */
function isHintRelatedToTitle(hint, title) {
  const hRaw = attributionCleanTitleText(hint || '');
  const tRaw = attributionCleanTitleText(title || '');
  if (!hRaw || !tRaw) return false;
  const stripPrefix = function(s) { return String(s).replace(/^[^:：]{1,12}[:：]\s*/, '').trim(); };
  const hStripped = stripPrefix(hRaw);
  const tStripped = stripPrefix(tRaw);
  const h = hStripped.toLowerCase();
  const t = tStripped.toLowerCase();
  if (!h || !t) return false;
  if (h === t) return true;
  if (h.length >= 4 && t.includes(h)) return true;
  if (t.length >= 4 && h.includes(t)) return true;
  const short = h.length < t.length ? h : t;
  const long = h.length < t.length ? t : h;
  if (short.length >= 4) {
    for (let i = 0; i <= short.length - 4; i++) {
      const sub = short.slice(i, i + 4);
      if (!sub.trim() || /^[\s:：,，。.]+$/.test(sub)) continue;
      if (long.includes(sub)) return true;
    }
  }
  return false;
}

function attributeNewNumbers({ prevIndex, currIndex, sessions }) {
  const nums = newNumbersSince(prevIndex, currIndex)
  if (!nums.length) return []
  // 先找出所有“查旧票”的会话：hint 与已有工单标题相关且该工单不是本次新号
  const existingTitles = []
  try {
    const allIdx = currIndex || {}
    for (const k of Object.keys(allIdx)) {
      if (nums.includes(Number(k))) continue
      const v = allIdx[k]
      const t = v && typeof v === 'object' ? String(v.title || '') : String(v || '')
      if (t) existingTitles.push(t)
    }
    if (prevIndex) {
      for (const k of Object.keys(prevIndex)) {
        if (nums.includes(Number(k))) continue
        const v = prevIndex[k]
        const t = v && typeof v === 'object' ? String(v.title || '') : String(v || '')
        if (t && !existingTitles.includes(t)) existingTitles.push(t)
      }
    }
  } catch (e) {}
  const isInvestigating = function (hint) {
    if (!hint) return false
    for (let i = 0; i < existingTitles.length; i++) {
      try { if (isHintRelatedToTitle(hint, existingTitles[i])) return true } catch (e) {}
    }
    return false
  }
  const candidates = (Array.isArray(sessions) ? sessions : [])
    .filter(function (s) {
      if (!isNumberAwaitStage(s)) return false
      if (s.hint && isInvestigating(s.hint)) return false
      return true
    })
    .sort(function (a, b) {
      const ca = Number(a.createdAt || 0); const cb = Number(b.createdAt || 0)
      if (ca !== cb) return ca - cb
      const ua = Number(a.updatedAt || 0); const ub = Number(b.updatedAt || 0)
      if (ua !== ub) return ua - ub
      return String(a.sessionId || '').localeCompare(String(b.sessionId || ''))
    })
  const out = []
  const used = new Set()
  for (let i = 0; i < nums.length; i++) {
    const num = nums[i]
    const info = (currIndex && currIndex[String(num)]) || null
    const title = info ? String(info.title || info.state || '') : ''
    const hasTitle = !!(info && typeof info === 'object' && info.title)
    let picked = null
    if (hasTitle) {
      for (let j = 0; j < candidates.length; j++) {
        const c = candidates[j]
        if (used.has(c.sessionId)) continue
        const hint = c.hint
        if (!hint) continue
        try { if (isHintRelatedToTitle(hint, title)) { picked = c; break; } } catch (e) {}
      }
      if (!picked) continue
    } else {
      for (let j = 0; j < candidates.length; j++) {
        const c = candidates[j]
        if (!used.has(c.sessionId)) { picked = c; break; }
      }
      if (!picked) break
    }
    used.add(picked.sessionId)
    out.push({ sessionId: picked.sessionId, number: num, title: title })
  }
  return out
}
