  warning: 'var(--vc-warn,#f59e0b)',
  error: 'var(--vc-danger,#ef4444)',
  accent: 'var(--vc-info,#38bdf8)',
  caption: 'var(--vc-mut,#94a3b8)',
  primary: 'var(--vc-ink,#e6edf3)',
